    ) {
    }

    public function prepareVisibleDataInList(UserPersonalApiKey $content): UserPersonalApiKeyAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(UserPersonalApiKey $content): UserPersonalApiKeyAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(UserPersonalApiKeyAttributes $attributes, ?UserPersonalApiKey $original = null): UserPersonalApiKeyAttributes
    {
        $this->logDebug("Copy with fixed for User personal api key");
        $span = $this->startSpan("Copy with fixed for  User personal api key");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new UserPersonalApiKeyPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(UserPersonalApiKeyAttributes $attributes, ?UserPersonalApiKey $original = null): UserPersonalApiKeyAttributes
    {
        $this->logDebug("Copy with hidden for User personal api key");
        $span = $this->startSpan("Copy with hidden for  User personal api key");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|UserPersonalApiKeyRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for User personal api key");
        $span = $this->startSpan("Check visibility of an iterator for  User personal api key");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new UserPersonalApiKeyRef($value));
            } elseif ($value instanceof UserPersonalApiKeyRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new UserPersonalApiKeyFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(UserPersonalApiKeyFilter $filter, ?UserPersonalApiKeyCursor $cursor = null): UserPersonalApiKeySlide
    {
        $this->logDebug("List visibles for User personal api key");
        $span = $this->startSpan("List visibles for  User personal api key");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (UserPersonalApiKey $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
