            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(UserPersonalApiKeyFilter $filter): int
    {
        $this->logDebug("Count visibles for update for User personal api key");
        $span = $this->startSpan("Count visibles for update for  User personal api key");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(UserPersonalApiKeyRef $ref): ?UserPersonalApiKey
    {
        $this->logDebug("Retrieve visible for User personal api key");
        $span = $this->startSpan("Retrieve visible for  User personal api key");
        try {
            $filter = new UserPersonalApiKeyFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(UserPersonalApiKeyRef $ref): ?UserPersonalApiKey
    {
        $this->logDebug("Retrieve visible for update for User personal api key");
        $span = $this->startSpan("Retrieve visible for update for  User personal api key");
        try {
            $filter = new UserPersonalApiKeyFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?UserPersonalApiKeyRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for User personal api key");
        $span = $this->startSpan("Check fields for fix for User personal api key");
        try {
            $result = $this->dispatcher->dispatch(new UserPersonalApiKeyCollectNonEditableFields(UserPersonalApiKey::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?UserPersonalApiKeyRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for User personal api key");
        $span = $this->startSpan("Check fields to hide for  User personal api key");
        try {
            $result = $this->dispatcher->dispatch(new UserPersonalApiKeyCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
