    private function visiblesReferences(UserPersonalApiKeyAttributes $attributes): UserPersonalApiKeyAttributes
    {
        $this->logDebug("Check visibility of parent references for User personal api key");
        $span = $this->startSpan("Check visibility of parent references for  User personal api key");
        try {
            $user = $attributes->getUser();
            if (null !== $user && !$this->userVisibilityService->checkVisibility($user)) {
                throw new NotFoundException("Unknown User " . ($user->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(UserPersonalApiKeyFilter $filter): UserPersonalApiKeyFilter
    {
        $this->logDebug("Compose visibility filter for User personal api key");
        $span = $this->startSpan("Compose visibility filter for  User personal api key");
        try {
            $result = $this->dispatcher->dispatch(new UserPersonalApiKeyRestrictFilterToVisibility($filter));
            return $result->userPersonalApiKeyFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(UserPersonalApiKey $value): bool
    {
        $this->logDebug("Check if item is visible for User personal api key");
