            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new UserPersonalApiKeyEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
